package main

import ("bufio"; "fmt"; "net"; "strings")

func handle(c net.Conn) {
    defer c.Close()
    r := bufio.NewReader(c)

    // 1. 逐行读到空行 —— bufio 帮你处理了缓冲和分行
    var reqLine string
    for i := 0; ; i++ {
        line, err := r.ReadString('\n')
        if err != nil { return }
        if i == 0 { reqLine = strings.TrimSpace(line) }
        if strings.TrimSpace(line) == "" { break }   // 头结束
    }

    // 2. 解析请求行
    parts := strings.Fields(reqLine)
    if len(parts) < 2 { return }
    path := parts[1]

    // 3+4. 业务 + 响应
    body := fmt.Sprintf("你请求了 %s", path)
    fmt.Fprintf(c, "HTTP/1.1 200 OK\r\n"+
        "Content-Type: text/plain; charset=utf-8\r\n"+
        "Content-Length: %d\r\n\r\n%s", len(body), body)
}

func main() {
    ln, _ := net.Listen("tcp", "127.0.0.1:8080")
    for {
        c, err := ln.Accept()
        if err != nil { continue }
        go handle(c)          // 每连接一个 goroutine(见 L04)
    }
}

