// C 版:核心是那个「读到 \r\n\r\n」的循环
void handle(int cfd) {
    char buf[8192];
    size_t got = 0;
    /* 1. 循环读到头结束标记 */
    while (got < sizeof(buf) - 1) {
        ssize_t n = recv(cfd, buf + got, sizeof(buf) - 1 - got, 0);
        if (n <= 0) return;
        got += (size_t)n;
        buf[got] = '\0';
        if (strstr(buf, "\r\n\r\n")) break;   /* 找到边界 */
    }

    /* 2. 解析请求行 */
    char method[16] = {0}, path[512] = {0};
    sscanf(buf, "%15s %511s", method, path);

    /* 3+4. 业务 + 响应 */
    char body[600];
    int blen = snprintf(body, sizeof(body), "你请求了 %s", path);
    char resp[1400];
    int rlen = snprintf(resp, sizeof(resp),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/plain; charset=utf-8\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n\r\n%s", blen, body);
    send_all(cfd, resp, (size_t)rlen);
}
